INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (2, 1, 1, 'Complete Beard & Hair Regrowth System (Minoxidil 5% + Biotin 10,000mcg + Derma Roller)', 'complete-beard-hair-regrowth-system', 'The definitive all-in-one grooming regimen for hair regrowth and thick beard development. Combining collagen-stimulating micro-needling, essential high-potency Biotin cellular nutrition, and extra-strength 5% Minoxidil solution.', 0, NULL, 20, 0, 'published', 1, NULL, '{"Included In Box":"Kirkland Minoxidil 5% (60ml), Puritan''s Pride Biotin 10,000mcg (50 softgels), 540 Micro-Needle Derma Roller System","Treatment Cycle":"Full 30-Day Intensive Activation Bundle","Needle Length":"0.5mm Titanium Micro-needles","Biotin Strength":"Ultra Mega 10,000 mcg Vitamin B7"}', 'Fast nationwide delivery with tamper-proof packaging.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (3, 1, 1, 'MET-Rx Creatine 4200 Muscle Strength & Power Booster (240 Capsules)', 'met-rx-creatine-4200-capsules', 'MET-Rx Creatine 4200 provides 4.2g of pure creatine monohydrate per serving to boost explosive power, elevate workout threshold, and stimulate lean muscle growth during gym resistance workouts.', 0, NULL, 18, 0, 'published', 1, NULL, '{"Quantity":"240 Fast-Release Capsules","Creatine Dose":"4,200 mg Pure Creatine Monohydrate per serving","Key Benefits":"Boosts Muscle Strength, Power, and Athletic Recovery","Brand":"MET-Rx"}', 'Available for immediate dispatch from Accra warehouse.', 0) ON CONFLICT (id) DO NOTHING;
