INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (37, 3, 6, 'Royal Crown Custom Engraved 4-Piece Timepiece & Jewelry Suite', 'royal-crown-custom-engraved-4piece-timepiece-jewelry-suite', 'A stunning personal statement suite in polished stainless steel. Features a luxury dress watch with diamond hour markers and custom dial crown engraving ("Kafui 👑"), paired with a matching engraved bar link bracelet, an engraved tag necklace, and an engraved comfort-fit band ring, presented in a red velvet jewelry box.', 0, NULL, 15, 0, 'published', 1, 'JWL-ROYAL-CROWN-009', '{"Watch Movement":"High precision quartz with date magnification cyclops","Material":"Solid 316L Stainless Steel, tarnish-free & hypoallergenic","Set Includes":"Watch + Bar Link Bracelet + Pendant Necklace + Band Ring","Personalization":"Custom name & royal crown laser engraving","Box":"Luxe crimson velvet lined jewelry case"}', 'Nationwide registered delivery across Ghana.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (38, 3, 9, '"The Boss" Executive Wooden Desk Stand & Leather Portfolio Set', 'the-boss-executive-wooden-desk-stand-leather-portfolio-set', 'Crafted for executives, pastors, entrepreneurs, and mentors. Includes a handcrafted solid pine desk organizer with smartphone / business card display stand laser-engraved with an inspirational scripture ("THE BOSS - May You Always Be Blessed, Philippians 4:19"), accompanied by an executive slate blue leather binder portfolio with magnetic clasp, a custom engraved metal pen, and an engraved wooden keychain.', 0, NULL, 14, 0, 'published', 0, 'GFT-BOSS-DESK-010', '{"Desk Organizer":"Natural solid wood pen holder & smartphone dock","Portfolio":"A5 Slate Blue Faux Leather Binder with magnetic buckle","Engraving":"Custom name and scripture dedication","Includes":"Desk Dock, A5 Binder, Ballpoint Pen, Wooden Keychain, Hamper Box"}', 'Same-day delivery in Accra. 24-48h nationwide.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (39, 3, 9, 'Blush Pink & Royal Blue Birthday Pamper Gift Box', 'blush-pink-royal-blue-birthday-pamper-gift-box', 'A vibrant celebration hamper featuring a dusty rose designer flap purse with gold monogram hardware, a 750ml bottle of Mega Non-Alcoholic Red Grape Sparkling Wine, a sparkling heart crystal tennis bracelet in gift box, Pink Love fragrance mist duo, blush pink slide sandals, and a 3-piece royal blue cotton towel set with satin ribbons.', 0, NULL, 12, 0, 'published', 0, 'GFT-PINK-BLUE-011', '{"Items Included":"Designer Handbag, Mega Non-Alcoholic Red Grape, Heart Tennis Bracelet, Slide Sandals, Towel Set, Perfume Set","Packaging":"Premium large rigid gift chest"}', 'Delivered securely in festive gift packaging.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (40, 3, 7, 'Bespoke Photo & Brand Custom Printed Shockproof Phone Cases', 'bespoke-photo-brand-custom-printed-shockproof-phone-cases', 'Transform your favorite memories, family portraits, artistic photography, or business logos into durable shockproof phone cases. Available for all iPhone models (iPhone 11 through iPhone 16 Pro Max) and Samsung Galaxy series. High-definition anti-scratch UV sublimation printing ensures vibrant, fade-proof colors with reinforced corner bumpers.', 0, NULL, 50, 0, 'published', 0, 'ELE-PHONE-CUSTOM-012', '{"Compatibility":"iPhone 11 - 16 Pro Max, Samsung Galaxy S & A Series","Print Quality":"HD UV Sublimation, Fade & Scratch Resistant","Protection":"Reinforced drop-proof TPU bumper with raised camera bezel"}', 'Custom printed and dispatched within 24-48 hours.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (41, 4, 4, 'Crime Scene "Evidence Never Lies" Washed Black Oversized Graphic Tee', 'crime-scene-evidence-never-lies-washed-black-oversized-tee', 'The signature heavyweight streetwear graphic tee from Crime Scene Clothing Line''s Case 001: "Truth in Silence" collection. Cut from 240 GSM pre-shrunk washed black cotton in an oversized streetwear silhouette. Features yellow crime scene tape and forensic chalk evidence markers on the back, and a minimalist chest print on the front.', 0, NULL, 30, 0, 'published', 1, 'CS-TEE-BLK-013', '{"Fabric":"100% Heavyweight Cotton (240 GSM)","Color":"Forensic Washed Black","Fit":"Relaxed / Oversized Streetwear Fit","Front Print":"Crime Scene Est. 2024 (Evidence Yellow)","Back Print":"Evidence Never Lies — Forensic Investigation Chalk Artwork","Origin":"Designed & Made in Ghana"}', 'Nationwide dispatch via rider and VIP parcel service.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (42, 4, 4, 'Crime Scene "Evidence Never Lies" Sand Beige Oversized Graphic Tee', 'crime-scene-evidence-never-lies-sand-beige-oversized-tee', 'Crafted in an earthy sand beige hue, this 240 GSM heavyweight oversized tee embodies the forensic investigative narrative: "Behind the tape lies more than just a scene. It holds the truth, the facts, and the justice that follows." Finished with distressed evidence graphic and crime scene tape back piece.', 0, NULL, 25, 0, 'published', 1, 'CS-TEE-BGE-014', '{"Fabric":"100% Combed Cotton (240 GSM)","Color":"Sand Beige / Desert Stone","Fit":"Oversized Streetwear Silhouette","Print":"Screen printed with distressed texture","Origin":"Accra, Ghana"}', 'Nationwide delivery across Ghana.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (43, 4, 4, 'Crime Scene "Truth Is Silent" Pure White Minimalist Streetwear Tee', 'crime-scene-truth-is-silent-pure-white-minimalist-tee', 'Clean, striking, and understated. Pure white heavyweight cotton tee featuring minimal "CRIME SCENE - EST 2026" chest typography, paired with a custom lower hem evidence case file patch with barcode detailing. Tagline: "For those who move in silence, but notice everything."', 0, NULL, 25, 0, 'published', 1, 'CS-TEE-WHT-015', '{"Fabric":"100% Ringspun Cotton (240 GSM)","Color":"Pure Optical White","Details":"Woven case file patch on lower hem, ribbed crewneck","Fit":"Modern boxy relaxed fit"}', 'Dispatched directly from Accra.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (44, 4, 4, 'Crime Scene "Observe. Record. Reveal." Washed Black Long-Sleeve Shirt', 'crime-scene-observe-record-reveal-washed-black-long-sleeve', 'Streetwear long-sleeve tee from the Evidence Collection. Crafted from soft-washed 240 GSM black cotton featuring distressed yellow typography down both sleeves ("OBSERVE. RECORD. REVEAL." on left sleeve, "SILENT SCENE. LOUD TRUTH." on right sleeve) and a full investigative evidence back print.', 0, NULL, 20, 0, 'published', 0, 'CS-LS-BLK-016', '{"Fabric":"100% Washed Cotton (240 GSM)","Sleeves":"Dual statement typography prints with ribbed wrist cuffs","Back Graphic":"Crime Scene Do Not Cross — Not Every Clue Is Obvious"}', 'Available for immediate dispatch nationwide.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (46, 4, 4, 'Crime Scene "Evidence Collection" Women''s Cropped Rib Tank Top', 'crime-scene-evidence-collection-womens-cropped-rib-tank-top', 'Edgy streetwear cropped tank top made from 220 GSM 2-way stretch rib-knit cotton. Features the iconic distressed crime scene evidence graphic on the front, minimal upper back branding, and a flattering body-contouring cropped cut.', 0, NULL, 22, 0, 'published', 0, 'CS-TNK-WOM-018', '{"Fabric":"220 GSM 2-Way Stretch Premium Ribbed Cotton","Fit":"Cropped Athletic / Streetwear Fit","Color":"Bone White / Ash","Print":"Front evidence marker composition with distressed caution tape"}', 'Available for immediate delivery across Ghana.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (47, 4, 4, 'Crime Scene "Follow The Evidence" Raw-Cut Sleeveless Muscle Streetwear Tee', 'crime-scene-follow-the-evidence-raw-cut-sleeveless-muscle-tee', 'High-impact sleeveless streetwear muscle tee featuring raw-cut open armholes, a relaxed oversized body, and the "Follow The Evidence, Not Opinions" forensic evidence front statement artwork. Perfect for gym sessions, concerts, and casual street culture.', 0, NULL, 20, 0, 'published', 0, 'CS-MSL-RAW-019', '{"Fabric":"240 GSM Heavyweight Cotton","Cut":"Raw-cut armhole edges with reinforced shoulder seams","Fit":"Boxy Oversized Streetwear Muscle Tee"}', 'Nationwide dispatch via rider and VIP parcel service.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO noleya_products (id, seller_id, category_id, name, slug, description, price_ghs, compare_price_ghs, stock_quantity, is_unlimited_stock, status, is_featured, sku, specifications, delivery_info, views_count) VALUES (49, 4, 4, 'Crime Scene Clothing Line — Complete SS26 Capsule Collection Lookbook', 'crime-scene-clothing-line-complete-ss26-capsule-collection', 'Complete multi-piece bundle from Crime Scene Clothing Line''s SS26 "Truth in Silence" debut. Includes 1 Washed Black Graphic Tee, 1 Sand Beige Oversized Tee, 1 Long-Sleeve Streetwear Shirt, and 1 Heavyweight Fleece Hoodie. A complete streetwear wardrobe curation representing authenticity, evidence, and Ghanaian urban fashion.', 0, NULL, 8, 0, 'published', 1, 'CS-BNDL-SS26-021', '{"Bundle Includes":"1x Washed Black Tee, 1x Sand Beige Tee, 1x Long-Sleeve Shirt, 1x Heavyweight Fleece Hoodie","Sizes Available":"S, M, L, XL, XXL (Customizable per item)","Packaging":"Limited edition evidence bag collector''s box"}', 'Premium VIP boxed delivery across Ghana.', 2) ON CONFLICT (id) DO NOTHING;
